float cbrt(float x) { return sign(x) * pow(abs(x), 1. / 3.); }

float helper(float x, float y)
{
    float a = -2. * y;
    float b = 4. * x - 1.;
    float c = 2. * y;

    float a3 = a / 3.;

    float p = b - a * a3;
    float q = a3 * (2. * a3 * a3 - b) + c;

    float Q = p / 3.;
    float R = q / 2.;
    float h = R * R + Q * Q * Q;

    if (h >= 0.)
    {
        h = sqrt(h);
        return cbrt(-R + h) + cbrt(-R - h) - a3;
    }
    else
    {
        float phi = acos(-R / sqrt(-Q * Q * Q));
        return 2.0 * sqrt(-Q) * cos(phi / 3.0) - a3;
    }
}

void halley(float x, float y, inout float t)
{
    for(int i = 0; i < 3; i++)
    {
        float C = cosh(t);
        float S = sinh(t);

        float f = (x - t) + (y - C) * S;
        float g = C * (y - 2. * C);
        float h = S * (y - 4. * C);

        t -= (f * g) / (g * g - .5 * f * h);
    }
}

float func(float x, float y, float t)
{
    x -= t;
    y -= cosh(t);
    return x * x + y * y;
}

float sdCosh(vec2 p, float a, float b) 
{
    float x = p.x, y = p.y;

    float t = a;
    float d = func(x, y, a);

    if (y > 2.)
    {
        float h = acosh(.5 * y) - .25 * y * sqrt(y * y - 4.);

        if (x <= -h)
        {
            float tmp = -log(helper(x, y));
            halley(x, y, tmp);

            if(tmp > a && tmp < b)
            {
                float dtmp = func(x, y, tmp);
                if(dtmp < d) t = tmp, d = dtmp;
            }
        }

        if (x >= h)
        {
            float tmp = log(helper(-x, y));
            halley(x, y, tmp);

            if(tmp > a && tmp < b)
            {
                float dtmp = func(x, y, tmp);
                if(dtmp < d) t = tmp, d = dtmp;
            }
        }
    }
    else
    {
        float tmp = sign(x) * log(helper(-abs(x), y));
        halley(x, y, tmp);

        if(tmp > a && tmp < b)
        {
            float dtmp = func(x, y, tmp);
            if(dtmp < d) t = tmp, d = dtmp;
        }
    }

    float dtmp = func(x, y, b);
    if(dtmp < d) t = b, d = dtmp;

    return sqrt(d);
}

// the core math comes from this wikipedia page:
// https://en.wikipedia.org/wiki/Catenary#Determining_parameters
//
// my main contribution here is solving for alpha,
// which has no closed form solution.
//
// we need to solve
//   sqrt(L^2 - v^2) = 2a * sinh(H / 2a)
//
// in this function:
//   L is L
//   v is u.y
//   H is u.x
//   a is alpha
float getAlpha(vec2 u, float L)
{
    // with the substitution
    //
    //   t = u.x / 2a
    //   k = sqrt(L^2 - u.y^2) / u.x
    //
    // the equation reduces to
    //
    //   kt = sinh(t)

    float k = sqrt(L * L - u.y * u.y) / u.x;

    float t;
    if (k < 9.3)
    {
        // near field approximation using the taylor series of sinh(x):
        //   sinh(x) = x + x^3/3! + x^5/5! + x^7/7! + ...
        //
        // substituting and rearranging gives:
        //   t * (5040 * (1 - k) + 840 * t^2 + 42 * t^4 + t^6) = 0
        //
        // t = 0 is the trivial root.
        // the remaining term is a cubic in t^2.
        // since there is always exactly one valid root,
        // we solve it using cardano's formula.
        float A = 2520. * k + 616.;
        float d = sqrt(A * A + 592704.);
        t = sqrt(cbrt(A + d) + cbrt(A - d) - 14.);
    }
    else
    {
        // far field approximation: sinh(x) ≈ e^x / 2
        //
        // solving k t = sinh(t) under this assumption gives:
        //   t = -W_{-1}(-1 / 2k)
        //
        // W_{-1} is the -1 branch of the lambert W function.
        // we use its asymptotic expansion:
        //
        //   L1 = ln(x)
        //   L2 = ln(-L1)
        //   W_{-1}(-x) ≈ L1 - L2 + (1 + (L2 - 2) / L1) * L2 / L1

        float L1 = log(2. * k);
        float L2 = log(L1);
        t = L1 + L2 + (1. + (2. - L2) / L1) * L2 / L1;
    }

    // two iterations of halley's method for refinement
    for (int i = 0; i < 2; i++)
    {
        float S = sinh(t);
        float C = cosh(t);
        float f = S - k * t;
        float g = C - k;
        float h = S;
        t -= f * g / (g * g - .5 * f * h);
    }

    // alpha = u.x / (2 * t)
    return u.x / (2. * t);
}

float sdCatenary(vec2 p, vec2 a, vec2 b, float L)
{
    if (a.x > b.x)
    {
        vec2 tmp = a;
        a = b;
        b = tmp;
    }

    vec2 u = b - a;

    float u2 = dot(u, u);
    if (u2 >= L * L)
    {
        vec2 pa = p - a;
        return length(pa - u * clamp(dot(pa, u) / u2, 0., 1.));
    }

    float alpha = getAlpha(u, L);

    vec2 m = (a + b) / 2.0;

    float H = atanh(u.y / L);

    vec2 offset = alpha * vec2(H, L * sqrt(1. / (L * L - u.y * u.y) + 1. / (4. * alpha * alpha))) - m;

    return alpha * sdCosh((p + offset) / alpha, (a.x + offset.x) / alpha, (b.x + offset.x) / alpha);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
    vec2 m = (2.0*iMouse.xy-iResolution.xy)/iResolution.y;

    vec2 a = vec2(1.0,0.6)*cos( iTime*0.5 + vec2(0.0,1.00) + 0.0 );
	vec2 b = vec2(1.0,0.6)*cos( iTime*0.5 + vec2(0.0,3.00) + 1.5 );

    float d = sdCatenary(p, a, b, 1.7);

	// coloring
    vec3 col = (d>0.0) ? vec3(0.9,0.6,0.3) : vec3(0.65,0.85,1.0);
    col *= 1.0 - exp(-6.0*abs(d));
	col *= 0.8 + 0.2*cos(150.0*d);
	col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,0.01,abs(d)) );

    if( iMouse.x>0.001 )
    {
    d = sdCatenary(m, a, b, 1.7);
    col = mix(col, vec3(1.0,1.0,0.0), 1.0-smoothstep(0.0, 0.005, abs(length(p-m)-abs(d))-0.0025));
    col = mix(col, vec3(1.0,1.0,0.0), 1.0-smoothstep(0.0, 0.005, length(p-m)-0.015));
    }

	fragColor = vec4(col,1.0);
}
